func (this *Bitbank) WithdrawAsync(code any, amount any, address any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.withdrawBody(ch, code, amount, address, optionalArgs...)
	return ch
}
func (this *Bitbank) withdrawBody(ch chan any, code any, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	tag := GetArg(optionalArgs, 0, nil)
	_ = tag
	params := GetArg(optionalArgs, 1, map[string]any{})
	_ = params
	tagparamsVariable := this.HandleWithdrawTagAndParams(tag, params)
	tag = GetValue(tagparamsVariable, 0)
	params = GetValue(tagparamsVariable, 1)
	if !IsTrue((InOp(params, "uuid"))) {
		panic(ExchangeError(Add(this.Id, " uuid is required for withdrawal")))
	}
	if IsTrue(IsEqual(this.Markets, nil)) {

		retRes101312 := (<-this.LoadMarketsAsync())
		PanicOnError(retRes101312)
	}
	var currency any = this.Currency(code)
	var request map[string]any = map[string]any{
		"asset":  GetValue(currency, "id"),
		"amount": amount,
	}

	response := (<-this.PrivatePostUserRequestWithdrawal(this.Extend(request, params)))
	PanicOnError(response)
	//
	//     {
	//         "success": 1,
	//         "data": {
	//             "uuid": "string",
	//             "asset": "btc",
	//             "amount": 0,
	//             "account_uuid": "string",
	//             "fee": 0,
	//             "status": "DONE",
	//             "label": "string",
	//             "txid": "string",
	//             "address": "string",
	//             "requested_at": 0
	//         }
	//     }
	//
	var data any = this.SafeDict(response, "data", map[string]any{})

	ch <- this.ParseTransaction(data, currency)
	return nil
}
func (this *Bitbank) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// withdraw
	//
	//     {
	//         "uuid": "string",
	//         "asset": "btc",
	//         "amount": 0,
	//         "account_uuid": "string",
	//         "fee": 0,
	//         "status": "DONE",
	//         "label": "string",
	//         "txid": "string",
	//         "address": "string",
	//         "requested_at": 0
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var txid any = this.SafeString(transaction, "txid")
	currency = this.SafeCurrency(nil, currency)
	return map[string]any{
		"id":          txid,
		"txid":        txid,
		"timestamp":   nil,
		"datetime":    nil,
		"network":     nil,
		"addressFrom": nil,
		"address":     nil,
		"addressTo":   nil,
		"amount":      nil,
		"type":        nil,
		"currency":    GetValue(currency, "code"),
		"status":      nil,
		"updated":     nil,
		"tagFrom":     nil,
		"tag":         nil,
		"tagTo":       nil,
		"comment":     nil,
		"internal":    nil,
		"fee":         nil,
		"info":        transaction,
	}
}
func (this *Bitbank) Nonce() any {
	return this.Milliseconds()
}
func (this *Bitbank) Sign(path any, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, "public")
	_ = api
	method := GetArg(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	body := GetArg(optionalArgs, 4, nil)
	_ = body
	var query any = this.Omit(params, this.ExtractParams(path))
	var url any = Add(this.ImplodeHostname(GetValue(GetValue(this.Urls, "api"), api)), "/")
	if IsTrue(IsTrue((IsEqual(api, "public"))) || IsTrue((IsEqual(api, "markets")))) {
		url = Add(url, this.ImplodeParams(path, params))
		if IsTrue(IsGreaterThan(GetArrayLength(ObjectKeys(query)), 0)) {
			url = Add(url, Add("?", this.Urlencode(query)))
		}
	} else {
		this.CheckRequiredCredentials()
		// bitbank supports two auth methods, see https://github.com/bitbankinc/bitbank-api-docs/blob/master/rest-api.md#authorization
		// 'timeWindow' (default): request time + validity window, stateless and safe for concurrent use of one key
		// 'nonce': legacy strictly-increasing nonce, kept as an escape hatch for clients with drifting clocks,
		// since bitbank offers no server time endpoint to compensate against
		var authMethod any = this.SafeString(this.Options, "authMethod", "timeWindow")
		var isTimeWindow bool = (IsEqual(authMethod, "timeWindow"))
		var requestTime string = ToString(this.Milliseconds())
		var timeWindow any = this.SafeString(this.Options, "timeWindow", "5000")
		var nonce string = ToString(this.Nonce())
		var auth any = nil
		if IsTrue(isTimeWindow) {
			auth = Add(requestTime, timeWindow)
		} else {
			auth = nonce
		}
		url = Add(url, Add(Add(this.Version, "/"), this.ImplodeParams(path, params)))
		if IsTrue(IsEqual(method, "POST")) {
			body = this.Json(query)
			auth = Add(auth, body)
		} else {
			auth = Add(auth, Add(Add(Add("/", this.Version), "/"), path))
			if IsTrue(IsGreaterThan(GetArrayLength(ObjectKeys(query)), 0)) {
				query = this.Urlencode(query)
				url = Add(url, Add("?", query))
				auth = Add(auth, Add("?", query))
			}
		}
		headers = map[string]any{
			"Content-Type":     "application/json",
			"ACCESS-KEY":       this.ApiKey,
			"ACCESS-SIGNATURE": this.Hmac(this.Encode(auth), this.Encode(this.Secret), sha256),
		}
		if IsTrue(isTimeWindow) {
			AddElementToObject(headers, "ACCESS-REQUEST-TIME", requestTime)
			AddElementToObject(headers, "ACCESS-TIME-WINDOW", timeWindow)
		} else {
			AddElementToObject(headers, "ACCESS-NONCE", nonce)
		}
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    body,
		"headers": headers,
	}
}
